python3 -c "
import os, pypdf
for f in os.listdir('/workspace/company_files/invoices'):
    if f.endswith('.pdf'):
        p = os.path.join('/workspace/company_files/invoices', f)
        try:
            reader = pypdf.PdfReader(p)
            text = ''.join([page.extract_text() for page in reader.pages])
            if any(k in text.lower() for k in ['donovan', 'big bend', '8400', 'ridgeview']):
                print(f, 'MATCHED:', text[:200].replace('\n', ' '))
        except Exception as e:
            pass
"
